PATCH::VELVET_GLITCH{
CLOCK0=13/16{3+3+2+2+3};
CLOCK1=7/8{2+2+3}@.83x;
CLOCK2=4/4{tresillo},phase=+1/16;

voice=contralto(breathy,close_mic,portamento);
ney=bolero(nocturne,overblown);
cimbalom=trip_hop(damped,metallic);
prepared_piano=maloya(syncopated,low_register);
subbass=dub(sine,sidechain=false);
claves=broken_bossa(dropouts=true);

HOOK=riff("1 b3 4 b2",legato=true);
HOOK->repeat(2)->granulate(1/8)->restore();

A<-voice%CLOCK1;
B<-cimbalom%CLOCK0;
C<-subbass%CLOCK2;
D<-ney%reverse(CLOCK1);

IF(A&&B){delay(cimbalom,1/16);smear(vowels);}
IF(B&&C){cancel(downbeat);keep(body_pulse);}
EVERY4{bitcrush(prepared_piano,18%);}
EVERY6{swap(ney,voice,phrase_end);}
EVERY9{drop(all_except=voice+subbass);}
EVERY11{HOOK->stutter(3)->glide;}

OUT{dark=true;humid=true;dry_vocal=true;
glitch=seductive;groove=lurching;
master_grid=false;hook_priority=MAX;}
}

